<script lang="ts">
 import {refreshAll} from '$app/navigation';
 import {page} from '$app/state';
 import {helpFor,faqs} from '#lib/client/help-content.ts';
 import {TOUR_VERSION,tourResumeIndex} from '#lib/client/onboarding-tour.ts';
 import {fieldHelp} from '#lib/client/field-help.ts';
 import {command} from '#lib/client/api.ts';
 import type {AppData} from '#lib/client/types.ts';
 import Icon from './Icon.svelte';
 let {data}:{data:AppData}=$props();let query=$state(''),busy=$state(false),error=$state('');
 const all=$derived(helpFor(data.context?.permissions??[]));
 const topicMap:Record<string,string>={customers:'customer',inquiries:'customer',quotes:'sales','change-orders':'sales',orders:'orders','work-packages':'orders',sites:'orders',deliveries:'orders',acceptances:'orders',defects:'orders',studio:'memorial',cemeteries:'memorial',graves:'memorial',fonts:'memorial',invoices:'finance',payments:'finance',suppliers:'purchasing','purchase-orders':'purchasing','supplier-invoices':'purchasing',stock:'inventory',inventory:'inventory',resources:'inventory',team:'team',dispatch:'dispatch',time:'time',leave:'time',documents:'documents',imports:'documents',reports:'reports',settings:'ai',account:'orientation',tasks:'orientation'};
 const topic=$derived(page.url.searchParams.get('tab')==='numbering'?'numbering':topicMap[page.url.searchParams.get('from')??'']??'orientation');
 const term=$derived(query.trim().toLocaleLowerCase('de-DE'));
 const matches=$derived(all.filter(g=>[g.title,g.intro,...g.steps].join(' ').toLocaleLowerCase('de-DE').includes(term)).sort((a,b)=>Number(b.id===topic)-Number(a.id===topic)));
 const answers=$derived(faqs.filter(f=>(f.q+' '+f.a).toLocaleLowerCase('de-DE').includes(term)));
 async function restart(resume=false){if(busy)return;busy=true;error='';try{await command('account.onboarding.update',undefined,{status:'in_progress',step:resume?tourResumeIndex(data.context?.permissions??[],data.summary.onboarding):0,guideVersion:TOUR_VERSION},data.summary.onboarding?.version);await refreshAll();if(document.querySelector('dialog.onboarding:not([open])'))window.dispatchEvent(new Event('schubert:tour:start'));}catch(cause){error=cause instanceof Error?cause.message:'Die Einführung konnte nicht gestartet werden.';}finally{busy=false;}}
</script>
<div class="page-heading"><div><h1>Wie können wir Ihnen helfen?</h1><p>Verständliche Schritte für Ihren Alltag. Ohne kostenpflichtige KI-Anfrage.</p></div><div class="inline-actions">{#if data.summary.onboarding?.status==='deferred'&&[2,TOUR_VERSION].includes(data.summary.onboarding?.guide_version)&&data.summary.onboarding?.step>0}<button class="btn primary" disabled={busy} onclick={()=>restart(true)}>Einführung fortsetzen</button>{/if}<button class="btn" disabled={busy} onclick={()=>restart()}><Icon name="refresh" size={16}/>{busy?'Wird vorbereitet …':'Einführung neu starten'}</button></div></div>
{#if data.summary.onboarding?.guide_version<TOUR_VERSION}<p class="field-help mb">Die Einführung umfasst jetzt auch Einkauf, Lager, Disposition und die weiteren freigegebenen Arbeitsbereiche. Starten Sie sie neu, um alle Stationen kennenzulernen.</p>{/if}
{#if error}<div class="notice error" role="alert">{error}</div>{/if}
<div class="help-search field" data-tour="help-search"><label for="help-search">Anleitungen und Fragen durchsuchen</label><div><Icon name="search" size={18}/><input id="help-search" type="search" bind:value={query} placeholder="Zum Beispiel: Grundriss, Rechnung, Arbeitszeit"/></div></div>
{#if data.summary.trainingMode}<div class="notice info help-test"><div><strong>Ihr Testbetrieb ist vorbereitet.</strong><p>Beginnen Sie mit einem Datensatz mit „TEST“ im Namen. Die zusammengehörigen Kunden, Aufträge und Planungen bilden Beispielszenarien. Änderungen daran dienen nur der Erprobung.</p></div></div>{/if}
{#if data.summary.helpModule}{@const module=data.summary.helpModule}<section class="panel context-help" aria-labelledby="context-help-title"><header class="panel-header"><div><h2 id="context-help-title">Diese Seite: {module.label}</h2><p>{module.description}</p></div><a class="btn small" href={'/'+module.slug}>Zur Seite zurück<Icon name="arrow" size={15}/></a></header><div class="panel-body"><p class="small">{module.readOnly?'Hier sehen Sie vorhandene Nachweise oder Referenzen. Öffnen Sie einen Eintrag für Details; Änderungen erfolgen im zugehörigen Fachablauf.':'Prüfen Sie zuerst die vorhandenen Einträge. Mit „'+module.singular+' anlegen“ erstellen Sie einen neuen Entwurf; ein Eintrag öffnet seine Akte. Pflichtfelder sind mit einem Sternchen markiert.'}</p>{#if module.fields?.length}<details class="mt"><summary>Was trage ich in die Felder ein?</summary><dl class="help-field-list">{#each module.fields as field}<div><dt>{field.label}{field.required?' *':''}</dt><dd>{fieldHelp(field)||'Tragen Sie die passende Angabe für diesen Vorgang ein. Unbekannte optionale Angaben können Sie später ergänzen.'}{#if field.options?.length}<span class="help-subtitle">Auswahl: {field.options.map((option:any)=>option.label).join(' · ')}</span>{/if}</dd></div>{/each}</dl></details>{/if}{#if module.actions?.length}<p class="field-help mt">Je nach Bearbeitungsstand und Berechtigung stehen diese Schritte zur Verfügung: {module.actions.map((action:any)=>action.label).join(' · ')}. Der Fachdialog erklärt die benötigten Angaben und Bestätigungen.</p>{/if}</div></section>{/if}
<div class="help-layout"><section class="panel" aria-labelledby="help-guides"><header class="panel-header"><h2 id="help-guides">Schritt für Schritt</h2><span class="small">{matches.length} Anleitungen</span></header>{#each matches as guide}<details class="help-item" open={!!term||!!page.url.searchParams.get('from')&&guide.id===topic}><summary><span><strong>{guide.title}</strong><span class="help-subtitle">{guide.intro}</span></span><Icon name="chevron" size={16}/></summary><div class="help-answer"><ol>{#each guide.steps as step}<li>{step}</li>{/each}</ol><a class="text-link" href={guide.href}>{guide.action}<Icon name="arrow" size={15}/></a></div></details>{/each}</section><section class="panel" aria-labelledby="help-faq"><header class="panel-header"><h2 id="help-faq">Häufige Fragen</h2></header>{#each answers as faq}<details class="help-item" open={!!term}><summary><strong>{faq.q}</strong><Icon name="chevron" size={16}/></summary><div class="help-answer"><p>{faq.a}</p></div></details>{/each}</section></div>
{#if !matches.length&&!answers.length}<div class="empty-state" role="status"><Icon name="search" size={26}/><h2>Keine passende Anleitung gefunden</h2><p>Versuchen Sie einen kürzeren Begriff wie „Plan“, „Zeit“ oder „Kosten“.</p><button class="btn" onclick={()=>query=''}>Suche zurücksetzen</button></div>{/if}
<p class="field-help mt">Fehlt eine Erklärung? Halten Sie Bereich, Aktion und Meldung fest und geben Sie diese an Ihren Superadmin weiter.</p>
<style>.context-help{margin-bottom:28px}.context-help .panel-header{flex-wrap:wrap;gap:16px}.context-help summary{min-height:44px;align-content:center;cursor:pointer;font-size:14px;font-weight:550}.help-field-list{margin:8px 0 0;max-width:75ch}.help-field-list>div+div{border-top:1px solid var(--line)}.help-field-list>div{padding:16px 0}.help-field-list dt{font-size:14px;font-weight:550}.help-field-list dd{font-size:13px;line-height:1.7;margin:7px 0 0;color:var(--muted)}
 .help-search{max-width:680px;margin-bottom:28px}.help-search>div{display:flex;align-items:center;position:relative}.help-search :global(svg){position:absolute;left:14px;color:var(--muted)}.help-search input{width:100%;padding-left:44px;min-height:48px}.help-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:28px;align-items:start}.help-item{border-top:1px solid var(--line)}.help-item summary{list-style:none;display:flex;gap:20px;align-items:center;justify-content:space-between;padding:22px 28px;cursor:pointer}.help-item summary::-webkit-details-marker{display:none}.help-item summary strong{font-size:14px;font-weight:550;line-height:1.5}.help-item summary :global(svg){flex:none;transition:transform .16s ease-out}.help-item[open] summary :global(svg){transform:rotate(90deg)}.help-subtitle{display:block;margin-top:7px;font-size:13px;line-height:1.65;color:var(--muted)}.help-answer{padding:0 28px 26px;font-size:14px;line-height:1.75;max-width:75ch}.help-answer ol{padding-left:20px;margin:0 0 20px}.help-answer li+li{margin-top:14px}.help-test{margin-bottom:28px}
 @media(max-width:1000px){.help-layout{grid-template-columns:1fr}}@media(max-width:760px){.help-item summary{padding:20px}.help-answer{padding:0 20px 24px}}@media(prefers-reduced-motion:reduce){.help-item summary :global(svg){transition:none}}
</style>
